// Valida la entrada y separa paradas con coordenadas de las que hay que geocodificar.
// Nunca lanza errores: si algo está mal devuelve valido=false para que se responda.
const cfg = $('Config').first().json;
const body = $('Webhook').first().json.body;
const inicio_ms = Date.now(); // para repartir el tiempo de las llamadas de optimización (ver README)

const enRango = (lat, lon) =>
  Number.isFinite(lat) && Number.isFinite(lon) &&
  lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180;
const aNumero = (v) => (v === null || v === undefined || v === '' ? NaN : Number(v));
const enteroPositivo = (v) => {
  const n = aNumero(v);
  return Number.isInteger(n) && n >= 1 ? n : NaN;
};
const invalido = (status, error, detalle) =>
  [{ json: { valido: false, status, error, detalle } }];

const depotLat = aNumero(cfg.DEPOT_LAT);
const depotLon = aNumero(cfg.DEPOT_LON);
if (!enRango(depotLat, depotLon) || (depotLat === 0 && depotLon === 0)) {
  return invalido(500, 'configuracion_incompleta', 'Definir DEPOT_LAT y DEPOT_LON (variables de entorno de n8n)');
}
// La API key de ORS se lee del entorno en los nodos HTTP; aquí solo se
// verifica que exista (nunca se copia a los datos de la ejecución).
let orsKey = '';
try {
  orsKey = String($env.OPENROUTESERVICE_API_KEY || '').trim();
} catch (e) {
  orsKey = '';
}
if (!orsKey) {
  return invalido(500, 'configuracion_incompleta', 'Definir OPENROUTESERVICE_API_KEY (variable de entorno de n8n)');
}

if (!body || !Array.isArray(body.paradas)) {
  return invalido(400, 'entrada_invalida', 'Se esperaba {"paradas": [...], "reglas": {...}}');
}

// Reglas de peso: primero las del backend ("reglas" del payload), luego las
// variables de entorno (CAPACIDAD_KG, UMBRAL_CASA_KG, MAX_VIAJES) y por último
// los defaults. Una regla presente pero inválida es un 400.
const DEFAULTS = { capacidad_kg: 1100, umbral_casa_kg: 800, max_viajes: 3 };
const ENTORNO = { capacidad_kg: 'CAPACIDAD_KG', umbral_casa_kg: 'UMBRAL_CASA_KG', max_viajes: 'MAX_VIAJES' };
const enviadas = body.reglas;
if (enviadas !== undefined && enviadas !== null && (typeof enviadas !== 'object' || Array.isArray(enviadas))) {
  return invalido(400, 'entrada_invalida', '"reglas" debe ser un objeto');
}
const reglas = {};
for (const clave of Object.keys(DEFAULTS)) {
  const dePayload = enviadas ? enviadas[clave] : undefined;
  if (dePayload !== undefined && dePayload !== null) {
    const n = enteroPositivo(dePayload);
    if (Number.isNaN(n)) {
      return invalido(400, 'entrada_invalida', 'reglas.' + clave + ' debe ser un entero >= 1');
    }
    reglas[clave] = n;
  } else {
    const deEntorno = enteroPositivo(cfg[ENTORNO[clave]]);
    reglas[clave] = Number.isNaN(deEntorno) ? DEFAULTS[clave] : deEntorno;
  }
}

const resueltas = [];
const pendientes = [];
const sin_resolver = [];
const ids_recibidos = [];
const vistos = new Set();

for (const p of body.paradas) {
  let id = p ? p.pedido_id : undefined;
  if (typeof id === 'string' && /^\d+$/.test(id)) id = Number(id);
  if (!Number.isInteger(id)) {
    return invalido(400, 'entrada_invalida', 'pedido_id debe ser entero: ' + JSON.stringify(p));
  }
  // peso_kg es obligatorio en toda parada: entero >= 1.
  const peso = enteroPositivo(p.peso_kg);
  if (Number.isNaN(peso)) {
    return invalido(400, 'entrada_invalida', 'peso_kg debe ser un entero >= 1 (pedido_id ' + id + ')');
  }
  // Un pedido_id repetido se considera una sola parada (la primera).
  if (vistos.has(id)) continue;
  vistos.add(id);
  ids_recibidos.push(id);

  const lat = aNumero(p.latitud);
  const lon = aNumero(p.longitud);
  const direccion = typeof p.direccion_texto === 'string' ? p.direccion_texto.trim() : '';

  if (enRango(lat, lon)) {
    resueltas.push({ pedido_id: id, latitud: lat, longitud: lon, peso_kg: peso });
  } else if (direccion) {
    pendientes.push({ pedido_id: id, direccion_texto: direccion, peso_kg: peso });
  } else {
    sin_resolver.push({ pedido_id: id, motivo: 'dirección no encontrada' });
  }
}

return [{ json: { valido: true, ids_recibidos, resueltas, pendientes, sin_resolver, reglas, inicio_ms } }];

// Junta el resultado de la geocodificación con las paradas que ya tenían coordenadas.
const cfg = $('Config').first().json;
const base = $('Normalizar').first().json;
const pendientes = $('Separar pendientes').all().map((i) => i.json);
const respuestas = $input.all();
const minConfianza = Number(cfg.CONFIDENCE_MIN);

const resueltas = [...base.resueltas];
const sin_resolver = [...base.sin_resolver];

pendientes.forEach((p, i) => {
  const r = respuestas[i] ? respuestas[i].json : null;
  if (!r || r.error || !Array.isArray(r.features)) {
    sin_resolver.push({ pedido_id: p.pedido_id, motivo: 'error de geocodificación' });
    return;
  }
  const f = r.features[0];
  const coords = f && f.geometry && f.geometry.coordinates;
  if (!f || !Array.isArray(coords) || coords.length < 2) {
    sin_resolver.push({ pedido_id: p.pedido_id, motivo: 'dirección no encontrada' });
    return;
  }
  const props = f.properties || {};
  // El confidence de ORS no basta: una dirección inventada puede volver con confidence 1 y
  // match_type "exact" apuntando al centroide de otra calle. Solo se acepta un punto exacto.
  if (props.layer !== 'address') {
    sin_resolver.push({ pedido_id: p.pedido_id, motivo: 'dirección no encontrada con precisión suficiente' });
    return;
  }
  const confianza = Number(props.confidence);
  if (!(confianza >= minConfianza)) {
    sin_resolver.push({ pedido_id: p.pedido_id, motivo: 'dirección ambigua' });
    return;
  }
  // ORS devuelve [lon, lat].
  const lon = Number(coords[0]);
  const lat = Number(coords[1]);
  if (!(lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180)) {
    sin_resolver.push({ pedido_id: p.pedido_id, motivo: 'error de geocodificación' });
    return;
  }
  resueltas.push({ pedido_id: p.pedido_id, latitud: lat, longitud: lon, peso_kg: p.peso_kg });
});

return [{ json: { ids_recibidos: base.ids_recibidos, resueltas, sin_resolver } }];

// Llega desde Normalizar (sin geocodificar) o desde Evaluar geocodificación; ambos con la misma forma.
// Aplica la restricción de peso antes de llamar a ORS y arma la primera solicitud de optimización
// (k vehículos). Ver el README de N8N/ para el reparto del tiempo.
const cfg = $('Config').first().json;
const base = $('Normalizar').first().json;
const d = $input.first().json;
const { capacidad_kg, umbral_casa_kg, max_viajes } = base.reglas;
const depot = [Number(cfg.DEPOT_LON), Number(cfg.DEPOT_LAT)];

const PLAZO_MS = 36000; // las llamadas de optimización deben terminar 36 s después de recibir la solicitud
const TIMEOUT_MAX_MS = 10000;
const TIMEOUT_MIN_MS = 2000;
const MAX_APARTADAS = 2; // paradas que Evaluar error de optimización puede apartar (ubicación sin ruta alcanzable)

// Una parada que por sí sola supera la capacidad no se puede cargar en ningún viaje.
const sin_resolver = [...d.sin_resolver];
const resueltas = [];
for (const p of d.resueltas) {
  if (p.peso_kg > capacidad_kg) {
    sin_resolver.push({ pedido_id: p.pedido_id, motivo: 'pedido excede la capacidad del camión' });
  } else {
    resueltas.push(p);
  }
}

const total = resueltas.reduce((s, p) => s + p.peso_kg, 0);
if (total > capacidad_kg * max_viajes) {
  return [{
    json: {
      valido: false,
      status: 400,
      error: 'carga_excede_capacidad',
      detalle: 'El peso total de las paradas (' + total + ' kg) supera capacidad_kg * max_viajes (' + capacidad_kg * max_viajes + ' kg)',
    },
  }];
}

// Funciones del reparto (se repiten en Evaluar reparto, que arma los reintentos).
const cuerpoOptimizacion = (k) => ({
  vehicles: Array.from({ length: k }, (_, i) => ({
    id: i + 1, profile: 'driving-car', start: depot, end: depot, capacity: [capacidad_kg],
  })),
  jobs: resueltas.map((p) => ({ id: p.pedido_id, location: [p.longitud, p.latitud], amount: [p.peso_kg] })),
});

const k0 = resueltas.length > 0 ? Math.max(1, Math.ceil(total / capacidad_kg)) : 0;
// Llamadas que pueden hacer falta: los intentos desde k0 hasta max_viajes, una reoptimización a la casa
// y un reintento por cada parada que se aparte por no tener ruta alcanzable.
const llamadas = resueltas.length > 0 ? (max_viajes - k0 + 1) + 1 + MAX_APARTADAS : 0;
const restante = base.inicio_ms + PLAZO_MS - Date.now();
const timeout_ms = llamadas > 0 ? Math.min(TIMEOUT_MAX_MS, Math.floor(restante / llamadas)) : 0;
const sin_tiempo = llamadas > 0 && timeout_ms < TIMEOUT_MIN_MS;

return [{
  json: {
    valido: true,
    ids_recibidos: d.ids_recibidos,
    // Si no hay tiempo para optimizar no se llama a ORS: Armar respuesta responde 502.
    resueltas: sin_tiempo ? [] : resueltas,
    sin_resolver,
    reglas: base.reglas,
    depot,
    k0,
    body_optimizacion: llamadas > 0 && !sin_tiempo ? cuerpoOptimizacion(k0) : null,
    timeout_ms,
    plan_listo: resueltas.length === 0 || sin_tiempo,
    fallo: sin_tiempo ? 'tiempo agotado antes de optimizar' : null,
    accion: 'directo',
    viajes_ors: [],
  },
}];

// Numera los viajes, arma {ruta, viajes, sin_resolver} y verifica el contrato antes de responder.
// Si algo no cuadra, valido=false y se responde 502 (nunca una ruta parcial).
const d = $input.first().json;
// Llega el plan ya listo en el item (sin reoptimización a la casa, sin paradas o con falla) o la respuesta
// de ORS de "Optimizar a casa (ORS)", que reemplazó el item: el plan se lee entonces de "Preparar viaje a
// casa", un nodo con una sola salida y una sola ejecución (no de un IF, cuyas dos salidas hacían ambigua
// la lectura por nombre).
const plan = d.plan_listo ? d : $('Preparar viaje a casa').first().json;
const casaOpt = d.plan_listo ? null : d;
const { capacidad_kg, umbral_casa_kg, max_viajes } = plan.reglas;

const porId = new Map(plan.resueltas.map((p) => [p.pedido_id, p]));
const sin_resolver = [...plan.sin_resolver];
const errores = [];
if (plan.fallo) errores.push(plan.fallo);

// Viajes de ORS: pedidos en orden de visita y peso con los pesos recibidos.
const viajes = (plan.viajes_ors || []).map((v) => ({ vehiculo: v.vehiculo, ids: [...v.ids], termina_en: 'planta' }));
const pesoDe = (ids) => ids.reduce((s, id) => s + (porId.has(id) ? porId.get(id).peso_kg : 0), 0);

// El viaje más liviano, reoptimizado hacia la casa: solo cambia su orden interno.
if (plan.accion === 'casa' && errores.length === 0) {
  const v = viajes.find((x) => x.vehiculo === plan.casa_vehiculo);
  const r = casaOpt && Array.isArray(casaOpt.routes) && (casaOpt.code === undefined || casaOpt.code === 0) ? casaOpt.routes[0] : null;
  const nuevos = r && Array.isArray(r.steps) ? r.steps.filter((s) => s.type === 'job').map((s) => s.id) : [];
  const mismos = v && nuevos.length === v.ids.length && new Set(nuevos).size === nuevos.length && nuevos.every((id) => v.ids.includes(id));
  const sinAsignar = casaOpt && Array.isArray(casaOpt.unassigned) && casaOpt.unassigned.length > 0;
  if (!v || !mismos || sinAsignar || casaOpt.routes.length !== 1) {
    errores.push('reoptimización hacia la casa inesperada');
  } else {
    v.ids = nuevos;
    v.termina_en = 'casa';
  }
}

// Numeración: los que terminan en la planta, de mayor a menor peso (empate: menor vehículo);
// el de la casa, si existe, es el último (y el más liviano).
const enPlanta = viajes.filter((v) => v.termina_en === 'planta')
  .sort((a, b) => pesoDe(b.ids) - pesoDe(a.ids) || a.vehiculo - b.vehiculo);
const enCasa = viajes.filter((v) => v.termina_en === 'casa');
const ordenados = [...enPlanta, ...enCasa];

const ruta = [];
const resumen = [];
ordenados.forEach((v, i) => {
  const numero = i + 1;
  v.ids.forEach((id, j) => {
    const p = porId.get(id);
    ruta.push({ pedido_id: id, viaje: numero, orden_entrega: j + 1, latitud: p.latitud, longitud: p.longitud });
  });
  resumen.push({ viaje: numero, peso_kg: pesoDe(v.ids), termina_en: v.termina_en, total_paradas: v.ids.length });
});

// Verificación del contrato (la misma que hace el backend).
const apariciones = new Map();
for (const x of [...ruta, ...sin_resolver]) {
  apariciones.set(x.pedido_id, (apariciones.get(x.pedido_id) || 0) + 1);
}
for (const id of plan.ids_recibidos) {
  if (apariciones.get(id) !== 1) errores.push('pedido_id ' + id + ' aparece ' + (apariciones.get(id) || 0) + ' veces');
}
for (const id of apariciones.keys()) {
  if (!plan.ids_recibidos.includes(id)) errores.push('pedido_id no recibido: ' + id);
}
ruta.forEach((r) => {
  if (!(r.latitud >= -90 && r.latitud <= 90 && r.longitud >= -180 && r.longitud <= 180)) {
    errores.push('coordenadas fuera de rango en ' + r.pedido_id);
  }
});
const total = resumen.length;
if (total > max_viajes) errores.push('hay ' + total + ' viajes y el máximo es ' + max_viajes);
resumen.forEach((v) => {
  const paradas = ruta.filter((r) => r.viaje === v.viaje);
  if (v.total_paradas < 1) errores.push('viaje ' + v.viaje + ' sin paradas');
  const ordenes = paradas.map((r) => r.orden_entrega);
  if (ordenes.some((o, i) => o !== i + 1)) errores.push('orden_entrega no consecutivo en el viaje ' + v.viaje);
  if (v.peso_kg > capacidad_kg) errores.push('el viaje ' + v.viaje + ' excede la capacidad');
  // "casa" solo en el último viaje, con V >= 2 y peso < umbral; y en ese caso es obligatoria.
  const esperado = v.viaje === total && total >= 2 && v.peso_kg < umbral_casa_kg ? 'casa' : 'planta';
  if (v.termina_en !== esperado) errores.push('termina_en inválido en el viaje ' + v.viaje);
  if (total >= 2 && v.viaje < total && v.peso_kg < resumen[total - 1].peso_kg) {
    errores.push('el último viaje no es el más liviano');
  }
});

return [{ json: { valido: errores.length === 0, errores, respuesta: { ruta, viajes: resumen, sin_resolver } } }];

// Evalúa cada respuesta de ORS Optimization: decide si hay que reintentar con un vehículo más,
// o si el reparto en viajes está listo y si el viaje más liviano debe terminar en la casa.
// Se ejecuta una vez por intento ($runIndex = 0 es el primero, con k0 vehículos).
const prep = $('Preparar optimización').first().json;
const base = $('Normalizar').first().json;
const opt = $input.first().json;
const { capacidad_kg, umbral_casa_kg, max_viajes } = prep.reglas;
const k = prep.k0 + $runIndex; // vehículos de la solicitud que se evalúa

const PLAZO_MS = 36000;
const TIMEOUT_MAX_MS = 10000;
const TIMEOUT_MIN_MS = 2000;
const MAX_APARTADAS = 2; // ver Evaluar error de optimización
const restante = () => base.inicio_ms + PLAZO_MS - Date.now();

const porId = new Map(prep.resueltas.map((p) => [p.pedido_id, p]));
const aNumero = (v) => (v === null || v === undefined || v === '' ? NaN : Number(v));

// El resultado siempre lleva el plan completo (lo lee Armar respuesta).
const plan = (extra) => ({
  plan_listo: true,
  valido: true,
  ids_recibidos: prep.ids_recibidos,
  resueltas: prep.resueltas,
  sin_resolver: prep.sin_resolver,
  reglas: prep.reglas,
  depot: prep.depot,
  accion: 'directo',
  fallo: null,
  viajes_ors: [],
  ...extra,
});
const fallo = (motivo) => [{ json: plan({ fallo: motivo }) }];

// 1. Rutas de ORS -> viajes (id de vehículo, pedidos en orden de visita, peso).
if (!opt || !Array.isArray(opt.routes) || (opt.code !== undefined && opt.code !== 0)) {
  return fallo('respuesta de optimización inesperada');
}
const vistos = new Set();
const viajes = [];
for (const r of opt.routes) {
  const ids = [];
  for (const s of Array.isArray(r.steps) ? r.steps : []) {
    if (s.type !== 'job') continue;
    if (!porId.has(s.id) || vistos.has(s.id)) return fallo('job desconocido o repetido: ' + s.id);
    vistos.add(s.id);
    ids.push(s.id);
  }
  if (ids.length === 0) continue; // vehículo sin usar
  const peso_kg = ids.reduce((s, id) => s + porId.get(id).peso_kg, 0);
  if (peso_kg > capacidad_kg) return fallo('un viaje excede la capacidad');
  viajes.push({ vehiculo: r.vehicle, ids, peso_kg });
}
// ORS devuelve cada job de la solicitud en una ruta o en "unassigned". Las que no aparecen son las que
// Evaluar error de optimización apartó por no tener ruta alcanzable (no se enviaron en esta solicitud).
const sinRuta = new Set((Array.isArray(opt.unassigned) ? opt.unassigned : []).map((u) => u.id));
const intentadas = prep.resueltas.filter((p) => vistos.has(p.pedido_id) || sinRuta.has(p.pedido_id));
const apartadas = prep.resueltas.filter((p) => !vistos.has(p.pedido_id) && !sinRuta.has(p.pedido_id));
const sinAsignar = intentadas.filter((p) => !vistos.has(p.pedido_id));

// 2. Lo que no se pudo empaquetar: un vehículo más (hasta max_viajes) y se vuelve a optimizar.
if (sinAsignar.length > 0 && k < max_viajes) {
  const siguiente = k + 1;
  // Llamadas que aún pueden hacer falta: intentos desde siguiente hasta max_viajes, la reoptimización a la
  // casa y los reintentos por paradas que aún se podrían apartar.
  const llamadas = (max_viajes - siguiente + 1) + 1 + (MAX_APARTADAS - apartadas.length);
  const timeout_ms = Math.min(TIMEOUT_MAX_MS, Math.floor(restante() / llamadas));
  if (timeout_ms < TIMEOUT_MIN_MS) return fallo('tiempo agotado reintentando la optimización');
  const depot = prep.depot;
  return [{
    json: plan({
      accion: 'reintentar',
      plan_listo: false,
      timeout_ms,
      body_optimizacion: {
        vehicles: Array.from({ length: siguiente }, (_, i) => ({
          id: i + 1, profile: 'driving-car', start: depot, end: depot, capacity: [capacidad_kg],
        })),
        jobs: intentadas.map((p) => ({ id: p.pedido_id, location: [p.longitud, p.latitud], amount: [p.peso_kg] })),
      },
    }),
  }];
}

// 3. Reparto final. Lo que siga sin asignar va a sin_resolver.
const sin_resolver = [
  ...prep.sin_resolver,
  ...apartadas.map((p) => ({ pedido_id: p.pedido_id, motivo: 'ubicación sin ruta alcanzable' })),
  ...sinAsignar.map((p) => ({ pedido_id: p.pedido_id, motivo: 'no asignable en la optimización' })),
];
const final = (extra) => [{ json: plan({ sin_resolver, viajes_ors: viajes, ...extra }) }];

if (viajes.length < 2) return final({});

// El viaje más liviano (en empate, el de mayor número de vehículo) es el último.
// Termina en la casa solo si pesa ESTRICTAMENTE menos que el umbral.
const liviano = viajes.reduce((a, b) => (b.peso_kg < a.peso_kg || (b.peso_kg === a.peso_kg && b.vehiculo > a.vehiculo) ? b : a));
if (!(liviano.peso_kg < umbral_casa_kg)) return final({});

// La casa solo existe en las variables de entorno de n8n: se valida aquí y nunca se copia a los datos.
let casaLat = NaN;
let casaLon = NaN;
try {
  casaLat = aNumero($env.CASA_LAT);
  casaLon = aNumero($env.CASA_LON);
} catch (e) {
  casaLat = NaN;
  casaLon = NaN;
}
const casaValida = Number.isFinite(casaLat) && Number.isFinite(casaLon) &&
  casaLat >= -90 && casaLat <= 90 && casaLon >= -180 && casaLon <= 180 && !(casaLat === 0 && casaLon === 0);
if (!casaValida) {
  return [{
    json: plan({
      sin_resolver,
      viajes_ors: viajes,
      accion: 'error_config',
      status: 500,
      error: 'configuracion_incompleta',
      detalle: 'Definir CASA_LAT y CASA_LON',
    }),
  }];
}

// Reoptimiza SOLO las paradas de ese viaje (el reparto entre viajes no cambia).
const timeout_casa_ms = Math.min(TIMEOUT_MAX_MS, restante());
if (timeout_casa_ms < TIMEOUT_MIN_MS) return fallo('tiempo agotado antes de reoptimizar hacia la casa');
return [{
  json: plan({
    sin_resolver,
    viajes_ors: viajes,
    accion: 'casa',
    casa_vehiculo: liviano.vehiculo,
    timeout_casa_ms,
    // Pedidos del viaje liviano; "Preparar viaje a casa" arma los jobs y el nodo HTTP agrega el destino
    // (la casa) desde $env: no pasa por los datos del flujo.
    casa_ids: liviano.ids,
  }),
}];

// Último paso antes de "Optimizar a casa (ORS)". Esa llamada reemplaza el item por la respuesta de ORS,
// así que "Armar respuesta" necesita volver a leer el plan: lo lee de ESTE nodo, que tiene una sola
// salida y se ejecuta una sola vez (por eso la lectura por nombre no es ambigua). También arma los
// jobs del viaje liviano; el destino (la casa) lo agrega el nodo HTTP desde $env.
const plan = $input.first().json;
const porId = new Map(plan.resueltas.map((p) => [p.pedido_id, p]));
return [{
  json: {
    ...plan,
    jobs_casa: plan.casa_ids.map((id) => {
      const p = porId.get(id);
      return { id, location: [p.longitud, p.latitud], amount: [p.peso_kg] };
    }),
  },
}];

// Falla de "Optimizar (ORS)" (timeout, 4xx, 5xx...). Un único caso tiene arreglo: ORS responde
// code 3 "Unfound route(s) from location [lon,lat]" cuando una parada está en un punto sin ruta
// alcanzable (p. ej. en el mar). Entonces se aparta esa parada a sin_resolver y se reintenta con
// las demás (máximo MAX_APARTADAS por solicitud). Cualquier otra falla, o un punto que no se pueda
// asociar a una parada, termina en 502 optimizacion_fallida (llega a Armar respuesta con "fallo").
// La entrada es el item que falló: trae body_optimizacion (la solicitud) y "error".
const prep = $('Preparar optimización').first().json;
const base = $('Normalizar').first().json;
const fallido = $input.first().json;
const { max_viajes } = prep.reglas;

const MAX_APARTADAS = 2; // paradas que se pueden apartar por este motivo en una solicitud
const TOLERANCIA_GRADOS = 0.0001; // ~11 m: ORS puede redondear las coordenadas que informa
const PLAZO_MS = 36000;
const TIMEOUT_MAX_MS = 10000;
const TIMEOUT_MIN_MS = 2000;
const MOTIVO = 'ubicación sin ruta alcanzable';

const plan = (extra) => ({
  plan_listo: true,
  valido: true,
  ids_recibidos: prep.ids_recibidos,
  resueltas: prep.resueltas,
  sin_resolver: prep.sin_resolver,
  reglas: prep.reglas,
  depot: prep.depot,
  accion: 'directo',
  fallo: null,
  viajes_ors: [],
  ...extra,
});
const fallo = (motivo) => [{ json: plan({ fallo: motivo }) }];

const body = fallido.body_optimizacion;
if (!body || !Array.isArray(body.jobs) || !Array.isArray(body.vehicles)) {
  return fallo('falló la optimización de ORS');
}
const err = fallido.error;
const mensaje = String(err && (err.message || err.description) ? (err.message || err.description) : '');
const m = /Unfound route\(s\) from location \[\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*\]/.exec(mensaje);
if (!m) return fallo('falló la optimización de ORS');

// La parada cuyo punto coincide (con tolerancia); si varias comparten el punto, todas.
const lon = Number(m[1]);
const lat = Number(m[2]);
const dist = (j) => Math.max(Math.abs(j.location[0] - lon), Math.abs(j.location[1] - lat));
const minima = Math.min(...body.jobs.map(dist));
if (!(minima <= TOLERANCIA_GRADOS)) return fallo('el punto sin ruta no corresponde a ninguna parada');
const coinciden = body.jobs.filter((j) => dist(j) <= minima + 1e-9);

const yaApartadas = prep.resueltas.filter((p) => !body.jobs.some((j) => j.id === p.pedido_id));
const apartadas = [...yaApartadas, ...prep.resueltas.filter((p) => coinciden.some((j) => j.id === p.pedido_id))];
if (apartadas.length > MAX_APARTADAS) return fallo('demasiadas paradas sin ruta alcanzable');

const sin_resolver = [
  ...prep.sin_resolver,
  ...apartadas.map((p) => ({ pedido_id: p.pedido_id, motivo: MOTIVO })),
];
const jobs = body.jobs.filter((j) => !coinciden.some((c) => c.id === j.id));
if (jobs.length === 0) {
  // No queda nada que optimizar: respuesta sin viajes, con todas en sin_resolver.
  return [{ json: plan({ sin_resolver }) }];
}

// Presupuesto de tiempo: llamadas que aún pueden hacer falta (este reintento con los mismos k
// vehículos, los intentos con más vehículos, la reoptimización a la casa y las paradas por apartar).
const k = body.vehicles.length;
const llamadas = (max_viajes - k + 1) + 1 + (MAX_APARTADAS - apartadas.length);
const restante = base.inicio_ms + PLAZO_MS - Date.now();
const timeout_ms = Math.min(TIMEOUT_MAX_MS, Math.floor(restante / llamadas));
if (timeout_ms < TIMEOUT_MIN_MS) return fallo('tiempo agotado reintentando la optimización');

return [{
  json: plan({
    sin_resolver,
    accion: 'apartar',
    plan_listo: false,
    timeout_ms,
    // Mismos vehículos (el intento k sigue contando por $runIndex en Evaluar reparto), sin las paradas apartadas.
    body_optimizacion: { vehicles: body.vehicles, jobs },
  }),
}];
